<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Services\ReportImportService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ReportController extends Controller
{
 public function index(Request $r):JsonResponse{$u=$r->attributes->get('cms_user');if($this->staff($u)){return response()->json(['batches'=>DB::table('report_batches')->orderByDesc('id')->paginate(20)]);}return $this->userReport($u->id,$r);}
 public function upload(Request $r,ReportImportService $s):JsonResponse{if(!$this->admin($r))return response()->json(['error'=>'Hanya admin yang dapat import report'],403);$d=$r->validate(['aggregator'=>['required','string','max:150'],'period'=>['required','date_format:Y-m'],'file'=>['required','file','max:51200','mimes:xlsx,xls,csv']]);try{$id=$s->import($d['file'],$d['aggregator'],$d['period'],$r->attributes->get('cms_user')->id);return response()->json(['success'=>true,'batch_id'=>$id],201);}catch(\Throwable $e){return response()->json(['error'=>$e->getMessage()],422);}}
 public function show(Request $r,int $id):JsonResponse{if(!$this->staff($r->attributes->get('cms_user')))return response()->json(['error'=>'Forbidden'],403);$b=DB::table('report_batches')->where('id',$id)->first();if(!$b)return response()->json(['error'=>'Report tidak ditemukan'],404);$rows=DB::table('report_rows as rr')->leftJoin('users as u','u.id','=','rr.matched_user_id')->where('rr.report_batch_id',$id)->select('rr.*','u.full_name as owner_name','u.company_name as owner_company','u.email as owner_email')->orderBy('rr.row_number')->paginate(50);return response()->json(['batch'=>$b,'rows'=>$rows]);}
 public function rates(Request $r,int $id):JsonResponse{if(!$this->admin($r))return response()->json(['error'=>'Forbidden'],403);$d=$r->validate(['rates'=>['required','array'],'rates.*'=>['numeric','gt:0']]);DB::table('report_batches')->where('id',$id)->update(['currency_rates_snapshot'=>json_encode($d['rates']),'updated_at'=>now()]);return response()->json(['success'=>true]);}
 public function recheck(Request $r,int $id,ReportImportService $s):JsonResponse{if(!$this->admin($r))return response()->json(['error'=>'Forbidden'],403);$s->rematchBatch($id);return response()->json(['success'=>true]);}
 public function finalize(Request $r,int $id):JsonResponse{if(!$this->admin($r))return response()->json(['error'=>'Forbidden'],403);$d=$r->validate(['confirm_unresolved'=>['boolean']]);try{DB::transaction(function()use($r,$id,$d){$b=DB::table('report_batches')->where('id',$id)->lockForUpdate()->first();if(!$b||$b->status!=='READY_FOR_REVIEW')throw new \RuntimeException('Report belum siap atau sudah difinalisasi.');$unresolved=DB::table('report_rows')->where('report_batch_id',$id)->whereIn('status',['NO_ACCOUNT','CONFLICT','INVALID'])->count();if($unresolved&&!($d['confirm_unresolved']??false))throw new \RuntimeException("Masih ada {$unresolved} baris belum cocok. Konfirmasi untuk melewatinya.");$rates=json_decode($b->currency_rates_snapshot?:'{}',true);$matched=DB::table('report_rows as rr')->leftJoin('users as u','u.id','=','rr.matched_user_id')->where('rr.report_batch_id',$id)->where('rr.status','MATCHED')->select('rr.*','u.aggregator_percentage as default_percentage')->get();$gross=$userTotal=$adminTotal=0;foreach($matched as $row){$currency=strtoupper($row->client_payment_currency?:'IDR');$rate=(float)($rates[$currency]??($currency==='IDR'?1:0));if($rate<=0)throw new \RuntimeException("Kurs {$currency} belum diisi.");$pct=(float)($row->user_percentage??$row->default_percentage??70);$g=round((float)$row->net_revenue*$rate);$ur=round($g*$pct/100);$ar=$g-$ur;DB::table('report_rows')->where('id',$row->id)->update(['exchange_rate'=>$rate,'gross_idr_decimal'=>$g,'gross_idr_final'=>$g,'user_percentage'=>$pct,'aggregator_percentage'=>100-$pct,'user_revenue'=>$ur,'aggregator_revenue'=>$ar,'updated_at'=>now()]);DB::table('user_revenue_ledger')->updateOrInsert(['report_row_id'=>$row->id,'user_id'=>$row->matched_user_id,'ledger_type'=>'ROYALTY'],['report_batch_id'=>$id,'sales_month'=>$row->sales_month,'platform'=>$row->platform,'country_region'=>$row->country_region,'artist_name'=>$row->artist_name,'release_title'=>$row->release_title,'track_title'=>$row->track_title,'upc'=>$row->upc_normalized,'isrc'=>$row->isrc_normalized,'quantity'=>$row->quantity,'original_currency'=>$currency,'original_net_revenue'=>$row->net_revenue,'exchange_rate_snapshot'=>$rate,'gross_idr_snapshot'=>$g,'user_percentage_snapshot'=>$pct,'aggregator_percentage_snapshot'=>100-$pct,'user_revenue_idr'=>$ur,'aggregator_revenue_idr'=>$ar,'status'=>'FINALIZED','finalized_at'=>now(),'created_at'=>now()]);$gross+=$g;$userTotal+=$ur;$adminTotal+=$ar;}DB::table('report_batches')->where('id',$id)->update(['status'=>'FINALIZED','finalized_by'=>$r->attributes->get('cms_user')->id,'finalized_at'=>now(),'gross_idr_total'=>$gross,'user_revenue_total'=>$userTotal,'aggregator_revenue_total'=>$adminTotal,'updated_at'=>now()]);});return response()->json(['success'=>true]);}catch(\Throwable $e){return response()->json(['error'=>$e->getMessage()],409);}}
 private function userReport(int $id,Request $r):JsonResponse{$summary=DB::table('user_revenue_ledger')->where('user_id',$id)->where('status','FINALIZED')->selectRaw('COALESCE(SUM(user_revenue_idr),0) total_revenue,COALESCE(SUM(quantity),0) total_quantity,COUNT(DISTINCT report_batch_id) total_batches,COUNT(DISTINCT isrc) total_tracks')->first();$rows=DB::table('user_revenue_ledger as l')->join('report_batches as b','b.id','=','l.report_batch_id')->where('l.user_id',$id)->select('l.*','b.report_period','b.aggregator_name')->orderByDesc('l.finalized_at')->paginate(30);$monthly=DB::table('user_revenue_ledger as l')->join('report_batches as b','b.id','=','l.report_batch_id')->where('l.user_id',$id)->groupBy('b.report_period')->orderBy('b.report_period')->selectRaw('b.report_period period,SUM(l.user_revenue_idr) revenue,SUM(l.quantity) quantity')->get();return response()->json(['summary'=>$summary,'rows'=>$rows,'monthly'=>$monthly]);}
 private function staff(object $u):bool{return in_array(strtolower($u->role),['admin','operator'],true);}private function admin(Request $r):bool{return strtolower($r->attributes->get('cms_user')->role)==='admin';}
}
